buy_code:
매수 = True

if not (관심종목 == 1):
    매수 = False

elif 시분초 < {b1_end}:
    # 밴드1: 09:00~b1_end, 소형주 첫 돌파. 시드 코어와 유사하되 각도보다 실제 직전고가 돌파+초당거래대금 폭발을 우선.
    if 시가총액 < {b1_cap_max}:
        if not (
            등락율 >= {b1_rate_min} and
            등락율 <= {b1_rate_max} and
            당일거래대금 >= {b1_day_money_min} and
            초당거래대금 >= {b1_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b1_burst_win}, 1) >= {b1_burst_mult} and
            체결강도 >= {b1_strength_min} and
            현재가 > 최고현재가({b1_break_win}, 1)
        ):
            매수 = False
    else:
        매수 = False

elif 시분초 < {b2_end}:
    # 밴드2: b1_end~b2_end, 중대형 독립 재발화. 후반부라 소형 급등이 아니라 유동성 있는 종목의 직전고가 재돌파+재가속만 허용.
    if {b2_cap_min} <= 시가총액 < {b2_cap_max}:
        if not (
            등락율 >= {b2_rate_min} and
            등락율 <= {b2_rate_max} and
            당일거래대금 >= {b2_day_money_min} and
            초당거래대금 >= {b2_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b2_burst_win}, 1) >= {b2_burst_mult} and
            체결강도 >= {b2_strength_min} and
            등락율각도({b2_angle_win}, 1) >= {b2_angle_min} and
            현재가 > 최고현재가({b2_break_win}, 1)
        ):
            매수 = False
    else:
        매수 = False

else:
    매수 = False

if 매수:
    self.Buy()

sell_code:
매도 = False

if 수익률 >= {take_profit}:
    매도 = True
elif 수익률 <= -{stop_loss}:
    매도 = True
elif 보유시간 >= {max_hold_sec}:
    매도 = True
elif 최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap}:
    매도 = True

if 매도:
    self.Sell()
